import{_ as r,l as o,o as e,c as d,v as t,p as l,x as n,d as s,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"断点回归","description":"","frontmatter":{"title":"断点回归","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rdd.md","filePath":"econ/rdd.md","lastUpdated":1789023840000}'),p={name:"econ/rdd.md"};function E(h,a,D,A,_,u){const i=o("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="断点回归" tabindex="-1">断点回归 <a class="header-anchor" href="#断点回归" aria-label="Permalink to &quot;断点回归&quot;">​</a></h1><div class="epigraph"><p>资格由连续变量是否越过门槛决定时，门槛两侧的人几乎一样，处理却跳一下；跳的是局部因果，不是全局 ATE。</p><footer>—— Thistlethwaite and Campbell, Regression-Discontinuity Analysis, 1960；Hahn, Todd and van der Klaauw, Econometrica 2001；Imbens and Lemieux, J. Econometrics 2008</footer></div><p><a href="/econ/staggered-did">上一课</a>在时间维度上拆 TWFE 加权。本课换截面设计：断点回归（RDD）。合成控制下一课对付「一个处理单位、没有门槛」。本课只钉清晰与模糊断点、局部识别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分数 \\(X\\) 过 \\(c\\) 则录取、则补贴、则受监管。\\(D=\\mathbf{1}\\{X\\ge c\\}\\)（清晰断点）。Hahn–Todd–van der Klaauw：若潜在结果的条件期望在 \\(c\\) 连续，而处理概率跳，则</p> \\[\\tau_{\\mathrm{SRD}}=\\frac{\\lim_{x\\downarrow c}\\mathbb{E}[Y\\mid X=x]-\\lim_{x\\uparrow c}\\mathbb{E}[Y\\mid X=x]}{\\lim_{x\\downarrow c}\\mathbb{E}[D\\mid X=x]-\\lim_{x\\uparrow c}\\mathbb{E}[D\\mid X=x]} \\]<p>清晰时分母为 1，\\(\\tau\\) 是门槛处的 ATE（在 \\(X=c\\) 的子总体）。缺口不是再讲教育回报，而是：识别是<strong>局部</strong>的，外推到远离 \\(c\\) 的人要另加假设。模糊断点（过门槛只提高处理概率）把 RDD 收成局部 IV，LATE 在门槛编译器上。</p><p><span class="marginnote">McCrary 密度检验：若人能精确操纵 \\(X\\)（报税、成绩修改），密度在 \\(c\\) 处不连续，连续性假设失败。Lee：不完全操纵下仍可能局部随机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>局部多项式在 \\(c\\) 两侧分别拟合，带宽用 Imbens–Kalyanaraman 或 Calonico–Cattaneo–Titiunik（CCT）的稳健偏误校正。不要用全局高阶多项式「穿过」整个 \\(X\\) 支持——Gelman–Imbens 警告过拟合与假断点。协变量应在 \\(c\\) 连续（安慰剂）；结果在 \\(c\\) 跳才是效应。标准误用 CCT 稳健或偏差校正后的。</p>',10)),(e(),l(m,null,{default:n(()=>[c(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%A9%B1%E5%8A%A8%E5%85%83%20X%22%5D%20--%3E%20C%5B%22%E9%97%A8%E6%A7%9B%20c%22%5D%0A%20%20C%20--%3E%20JUMPD%5B%22D%20%E8%B7%B3%22%5D%0A%20%20CONT%5B%22Y(0)%2CY(1)%20%E8%BF%9E%E7%BB%AD%22%5D%20--%3E%20TAU%5B%22%E9%97%A8%E6%A7%9B%E5%A4%84%E6%95%88%E5%BA%94%22%5D%0A%20%20JUMPD%20--%3E%20TAU%0A%20%20MAN%5B%22%E7%B2%BE%E7%A1%AE%E6%93%8D%E7%BA%B5%22%5D%20--%3E%20FAIL%5B%22%E5%AF%86%E5%BA%A6%E4%B8%8D%E8%BF%9E%E7%BB%AD%3A%20%E8%AF%86%E5%88%AB%E5%9D%8F%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>模糊：第一阶段是 \\(D\\) 在 \\(c\\) 的跳，排除是「门槛只通过 \\(D\\) 进 \\(Y\\)」。弱第一阶段同样适用上一课弱工具逻辑。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是局部随机：在 \\(c\\) 的一个小邻域，谁略高谁略低像抛硬币——若不能精确操纵。DiD 用时间平行；RDD 用驱动元连续。两者都是用设计逼近随机化，而不是用更长的控制清单。</p><p>与 IV：模糊 RDD 就是门槛工具。排除失败的例子：门槛同时触发另一项政策（打包改革）。那是复合处理，不是 \\(\\tau\\) 对单一 \\(D\\)。</p><p><span class="marginnote">离散驱动元（整数分数）时，局部随机化思路（Cattaneo 等）比连续密度更贴：比较 \\(c-1\\) 与 \\(c\\) 两个质量点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某个奖学金断点的估计外推成全国教育政策乘数。带宽选择有偏误–方差权衡；报告对带宽的敏感是设计的一部分。多门槛、多驱动元是延伸。下一课合成控制：没有 \\(c\\)，只有一个处理地区和一群候选对照。</p><p>后课默认：RDD 的参数是 \\(X=c\\) 处（清晰）或门槛编译器（模糊）；连续性加不可精确操纵。全局多项式不是默认。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>清晰 RDD：门槛处 ATE，靠 \\(Y(d)\\) 连续、\\(D\\) 跳。</li><li>模糊 RDD：局部 IV；分母是处理概率的跳。</li><li>操纵密度、打包政策，都会毁掉排除或连续性。</li><li>局部多项式 + 稳健带宽，避免全局高阶拟合。</li><li>出处：Thistlethwaite and Campbell 1960；Hahn, Todd and van der Klaauw 2001；Imbens and Lemieux 2008；Calonico, Cattaneo and Titiunik。</li></ul>',10))])}const b=r(p,[["render",E]]);export{B as __pageData,b as default};
